#!/usr/bin/env python3
"""Generate the AI Skunk Works static site (no dependencies). Run: python3 build.py"""
import os
NAV=[("About","/about/"),("Agents","/agents/"),("Projects","/projects/"),("Students","/students/"),("Industry","/industry/")]
def page(path,title,body,desc,current=None):
    nav="".join(f'<li><a href="{h}"{" aria-current=\"page\"" if h==current else ""}>{n}</a></li>' for n,h in NAV)
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{desc}"><title>{title}</title><link rel="stylesheet" href="/styles.css"></head>
<body><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><div class="container nav-wrap"><a class="brand" href="/"><span>AI Skunk Works<small>at Northeastern University</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="primary-nav" aria-label="Open navigation">&#9776;</button><nav aria-label="Primary navigation"><ul class="nav-list" id="primary-nav">{nav}<li><a class="nav-cta" href="/contact/">Pitch an idea</a></li></ul></nav></div></header>
<main id="main">{body}</main>
<footer class="site-footer"><div class="container footer-grid"><div><h3>AI Skunk Works</h3><p>A small team that builds working AI prototypes fast, at Northeastern University.</p></div><div><h3>Explore</h3><ul><li><a href="/about/">About</a></li><li><a href="/agents/">Agents</a></li><li><a href="/projects/">Projects</a></li></ul></div><div><h3>Connect</h3><ul><li><a href="/students/">Students</a></li><li><a href="/industry/">Industry</a></li><li><a href="/contact/">Pitch an idea</a></li></ul></div></div><div class="container footer-bottom">&copy; 2026 AI Skunk Works &middot; Northeastern University</div></footer>
<script src="/site.js"></script></body></html>'''
    d=os.path.join(os.path.dirname(os.path.abspath(__file__)),path)
    os.makedirs(os.path.dirname(d),exist_ok=True); open(d,"w").write(html)
def intro(eyebrow,h,p,cls): return f'<section class="page-intro page-intro--{cls}"><div class="container"><p class="eyebrow">{eyebrow}</p><h1>{h}</h1><p>{p}</p></div></section>'
def cards(items,n): return f'<div class="grid grid-{n}">'+"".join(f'<article class="card"><h3>{t}</h3><p>{p}</p></article>' for t,p in items)+'</div>'

home='''<section class="hero"><div class="container hero-layout"><div class="hero-copy"><p class="eyebrow">AI Skunk Works &middot; Northeastern University</p><h1>Small team. Hard problem. Working prototype.</h1><p class="lede">AI Skunk Works builds and tests AI systems quickly, with students, faculty, and partners who would rather learn from something that runs than from a slide that promises.</p><div class="hero-actions"><a class="button" href="/agents/">Adopt an agent</a><a class="button secondary" href="/contact/">Pitch an idea</a></div></div><aside class="hero-event"><p class="eyebrow">How we work</p><h2>Prototype first. Evaluate honestly. Share what we learn.</h2><p class="hero-event-meta">Small teams &middot; short cycles &middot; real tests</p><a class="hero-event-register" href="/about/">About the approach <span aria-hidden="true">&rarr;</span></a></aside></div></section>
<section class="section"><div class="container"><div class="section-heading"><div><p class="eyebrow">Why a skunk works</p><h2>Speed comes from focus.</h2></div><p>The name comes from a tradition of small, autonomous engineering teams given a hard problem and room to solve it. We borrow the idea for AI: fewer meetings, a clear question, a build that can be tested.</p></div><div class="grid grid-4"><article class="card audience-card"><span class="number">01</span><h3>Pick a real problem</h3><p>Start from a question someone actually needs answered.</p></article><article class="card audience-card"><span class="number">02</span><h3>Build the smallest thing</h3><p>The quickest system that can be tried and broken.</p></article><article class="card audience-card"><span class="number">03</span><h3>Test it against reality</h3><p>Evaluate with data, failure cases, and honest limits.</p></article><article class="card audience-card"><span class="number">04</span><h3>Share the result</h3><p>Publish what worked, what did not, and why.</p></article></div></div></section>
<section class="section"><div class="container two-col"><div><p class="eyebrow">Agentic AI</p><h2>1,877 agents. All open for improvement.</h2><p>Agentic AI is a project to collect agent designs, run them in more than one form, and be honest about what has been tested. The full library is here, and most of it is unfinished on purpose: specifications to review, tests to write, ports to build.</p><p>If you are part of AI Skunk Works, pick an agent, make it better, and send the result back.</p><a class="button" href="/agents/">Browse the agents</a> <a class="button secondary" href="/agents/contribute/">How to contribute</a></div><ul class="list"><li><strong>Review</strong> a draft specification.</li><li><strong>Test</strong> it with fixtures and record the evidence.</li><li><strong>Port</strong> it to Python, LangGraph, CrewAI or Pydantic AI.</li><li><strong>Extend</strong> it with new tools, guardrails or evaluations.</li></ul></div></section>
<section class="section alt"><div class="container two-col"><div><p class="eyebrow">Who it is for</p><h2>Bring a problem, a skill, or both.</h2><p>Students gain build experience on live problems. Faculty and partners get a fast, low-risk way to find out whether an AI idea is worth more investment.</p><a class="button secondary" href="/contact/">Pitch an idea</a></div><ul class="list"><li><strong>Students</strong> join teams and ship real work.</li><li><strong>Faculty</strong> test research ideas as prototypes.</li><li><strong>Industry</strong> bring a scoped challenge.</li><li><strong>Everyone</strong> gets an honest write-up.</li></ul></div></section>'''
page("index.html","AI Skunk Works | Rapid AI Prototyping at Northeastern",home,"AI Skunk Works at Northeastern University: small teams building and testing AI prototypes quickly.")
page("about/index.html","About | AI Skunk Works",intro("A small, fast AI team","About AI Skunk Works","AI Skunk Works is a prototyping group at Northeastern University that turns AI questions into working systems.","about")+f'''<section class="section"><div class="container two-col"><div><p class="eyebrow">Our mission</p><h2>Find out quickly whether an AI idea works.</h2></div><div><p>We keep teams small and cycles short. Each project starts with a specific question, produces something that can be run, and ends with an honest account of the results, including the failures.</p><p>The work is open to students, faculty, and outside partners who want to learn by building.</p></div></div></section><section class="section alt"><div class="container">{cards([("Prototype","Working software over proposals."),("Evaluate","Tests, failure cases, and stated limits."),("Teach","Every build is a chance to learn in public."),("Partner","Northeastern talent applied to real challenges.")],4)}</div></section>''','About AI Skunk Works at Northeastern.',"/about/")
page("projects/index.html","Projects | AI Skunk Works",intro("Build &middot; test &middot; report","Projects","Prototypes and experiments from the group. Profiles are added as work becomes ready to share.","research")+f'''<section class="section"><div class="container">{cards([("Project profiles","Coming soon. Each profile will state the question, what was built, how it was tested, and what we found."),("Open prototypes","Coming soon. Code and demos will be linked here when they are ready to share."),("Write-ups","Coming soon. Short, honest reports on results and limits.")],3)}<p style="margin-top:2rem">Have something you want built and tested? <a href="/contact/">Pitch an idea</a>.</p></div></section>''','Projects from AI Skunk Works.',"/projects/")
page("students/index.html","Students | AI Skunk Works",intro("Learn by shipping","For Students","Join a small team, work on a live problem, and leave with something you built and can explain.","students")+f'''<section class="section"><div class="container">{cards([("Join a build","Work on a scoped prototype with a clear question and a short timeline."),("Build a portfolio","Turn project work into a clear story: what you built, how you tested it, what you learned."),("Work with partners","Meet faculty and industry collaborators through real problems.")],3)}<p style="margin-top:2rem"><a class="button" href="/contact/">Tell us what you want to build</a></p></div></section>''','Student opportunities at AI Skunk Works.',"/students/")
page("industry/index.html","Industry | AI Skunk Works",intro("Bring a real problem","For Industry","Test an AI idea with a small Northeastern team before committing a large budget.","industry")+f'''<section class="section"><div class="container">{cards([("Scoped prototypes","A defined challenge, a short cycle, and a result you can evaluate."),("Student projects","Give students a meaningful problem and see what they produce."),("Guest talks","Share the engineering reality behind AI systems.")],3)}<p style="margin-top:2rem"><a class="button" href="/contact/">Start a conversation</a></p></div></section>''','Industry partnerships with AI Skunk Works.',"/industry/")
page("contact/index.html","Pitch an Idea | AI Skunk Works",intro("Start a conversation","Pitch an idea","Tell us the problem, who it matters to, and what a useful result would look like.","contact")+'''<section class="section"><div class="container two-col"><div><h2>Send a short note</h2><p>A few sentences is enough: the question, the data or systems involved, and your timeline. We will reply with a suggested next step.</p><p>Please avoid including sensitive personal information.</p></div><div><a class="button" href="mailto:bear@bearbrown.co?subject=AI%20Skunk%20Works%20idea">Email the team</a></div></div></section>''','Contact AI Skunk Works.')

# ---- Agents (Agentic AI) ----
REPO="https://github.com/nikbearbrown/Agents"
page("agents/index.html","Agents | AI Skunk Works",intro("Agentic AI &middot; open for improvement","Agents","Every agent in the library is a starting point. Students and Skunk Works members are invited to review, test, port, and extend them.","research")+'''<section class="section"><div class="container">
<div class="callout"><h3>Pick one and make it better</h3><p>Most agents here are source-derived drafts that have not been run. That is the opportunity. Open one, see what is unresolved, and take a piece of it. <a href="/agents/contribute/">How to contribute &rarr;</a></p></div>
<form class="agent-filters" id="agent-filters" role="search" style="display:grid;gap:.75rem;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));margin:2rem 0 1rem">
<label>Search<br><input id="q" type="search" placeholder="e.g. Telegram, Gmail, scraper" style="width:100%;padding:.6rem;border:1px solid var(--line)"></label>
<label>Category<br><select id="cat" style="width:100%;padding:.6rem;border:1px solid var(--line)"><option value="">All categories</option></select></label>
<label>Size<br><select id="size" style="width:100%;padding:.6rem;border:1px solid var(--line)"><option value="">Any size</option><option value="s">Small (up to 6 nodes) &mdash; good first picks</option><option value="m">Medium (7&ndash;15)</option><option value="l">Large (16+)</option></select></label>
</form>
<p id="count" aria-live="polite" class="meta"></p>
<div class="grid grid-3" id="results"></div>
<p><button class="button secondary" id="more" type="button" hidden>Show more</button></p>
<noscript><p>This library needs JavaScript. You can also browse it on <a href="'''+REPO+'''">GitHub</a>.</p></noscript>
</div></section><script src="/agents.js"></script>''','Browse the Agentic AI library of 1,877 agents.',"/agents/")
page("agents/view/index.html","Agent | AI Skunk Works",'''<section class="page-intro page-intro--research"><div class="container"><p class="eyebrow"><a href="/agents/">&larr; All agents</a></p><h1 id="a-title">Loading&hellip;</h1><p id="a-purpose"></p></div></section>
<section class="section"><div class="container" id="a-body"></div></section>
<script src="https://cdn.jsdelivr.net/npm/mermaid@10.9.1/dist/mermaid.min.js"></script><script src="/agents.js"></script>''','An agent in the Agentic AI library.',"/agents/")
page("agents/contribute/index.html","Contribute | AI Skunk Works",intro("Students and Skunk Works members","Improve an agent","The library only gets better if people work on it. Here is how to take a piece, do it well, and hand it back.","students")+f'''<section class="section"><div class="container two-col"><div><p class="eyebrow">Ways to help</p><h2>Pick the job that fits your time.</h2><p>Every agent page lists what is unresolved. Start there.</p></div><ul class="list"><li><strong>Review</strong> a draft specification: confirm the purpose, inputs, outputs and side effects.</li><li><strong>Test</strong> an agent with synthetic fixtures and record exactly what ran.</li><li><strong>Port</strong> it to Plain Python, Pydantic AI, CrewAI or LangGraph.</li><li><strong>Extend</strong> it: add a tool, a guardrail, an evaluation, or a failure test.</li><li><strong>Fix</strong> a source problem such as a broken connection or a missing credential note.</li></ul></div></section>
<section class="section alt"><div class="container"><div class="grid grid-4"><article class="card"><span class="number">01</span><h3>Choose</h3><p>Browse the library. Small agents (up to 6 nodes) make good first picks.</p></article><article class="card"><span class="number">02</span><h3>Claim</h3><p>Open a GitHub issue on the Agents repository saying which agent and which piece you are taking.</p></article><article class="card"><span class="number">03</span><h3>Build</h3><p>Follow the architecture and contribution contract. Add your work beside the existing implementation; do not duplicate the agent.</p></article><article class="card"><span class="number">04</span><h3>Show evidence</h3><p>Label results honestly and send a pull request.</p></article></div></div></section>
<section class="section"><div class="container two-col"><div><p class="eyebrow">Ground rules</p><h2>Evidence means what it says.</h2></div><div><p>A planned folder or an untested prompt is not a working implementation. Use the status labels: <em>source-available</em>, <em>planned</em>, <em>fixture-tested</em> (local deterministic tests, run and recorded) and <em>live-tested</em> (needs a dated, scoped receipt).</p><p>Never commit credentials or private data. Test with synthetic inputs. Keep each source's original attribution and license; curation is not a claim of authorship.</p><a class="button" href="{REPO}/blob/main/ARCHITECTURE.md">Read the contribution contract</a> <a class="button secondary" href="{REPO}/issues">Open or claim an issue</a></div></div></section>''','How to contribute to the Agentic AI library.',"/agents/")
